{"file_path":"src/heap.js","content":"/**
 * Binary min-heap with an index from key to position.
 *
 * Entries are kept in an array satisfying the heap property; a parallel map
 * from key to array index lets keyed operations locate an entry in O(1) and
 * then repair the heap in O(log n). Ties in priority are broken by an
 * insertion sequence number that is stamped once and never changes, so an
 * entry whose priority is raised and then lowered back still leaves before
 * entries pushed after it.
 */
export class IndexedHeap {
  /** @type {Array<{key: string, priority: number, seq: number}>} */
  #items = [];

  /** @type {Map<string, number>} */
  #positions = new Map();

  /** @type {number} */
  #nextSeq = 0;

  /**
   * Validates that a key is a string.
   * @param {unknown} key Candidate key.
   * @returns {void}
   */
  static #checkKey(key) {
    if (typeof key !== 'string') throw new TypeError('key must be a string');
  }

  /**
   * Validates that a priority is a finite number.
   * @param {unknown} priority Candidate priority.
   * @returns {void}
   */
  static #checkPriority(priority) {
    if (typeof priority !== 'number' || !Number.isFinite(priority)) {
      throw new TypeError('priority must be a finite number');
    }
  }

  /**
   * Compares two entries by priority, then by insertion order.
   * @param {{priority: number, seq: number}} a First entry.
   * @param {{priority: number, seq: number}} b Second entry.
   * @returns {boolean} True when a must leave before b.
   */
  static #lessThan(a, b) {
    return a.priority < b.priority || (a.priority === b.priority && a.seq < b.seq);
  }

  /**
   * Swaps two entries and keeps the index in sync.
   * @param {number} i First index.
   * @param {number} j Second index.
   * @returns {void}
   */
  #swap(i, j) {
    const items = this.#items;
    [items[i], items[j]] = [items[j], items[i]];
    this.#positions.set(items[i].key, i);
    this.#positions.set(items[j].key, j);
  }

  /**
   * Moves the entry at an index up until the heap property holds.
   * @param {number} index Starting index.
   * @returns {void}
   */
  #siftUp(index) {
    const items = this.#items;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (IndexedHeap.#lessThan(items[index], items[parent])) {
        this.#swap(index, parent);
        index = parent;
      } else {
        break;
      }
    }
  }

  /**
   * Moves the entry at an index down until the heap property holds.
   * @param {number} index Starting index.
   * @returns {void}
   */
  #siftDown(index) {
    const items = this.#items;
    const n = items.length;
    for (;;) {
      const left = index * 2 + 1;
      const right = left + 1;
      let smallest = index;
      if (left < n && IndexedHeap.#lessThan(items[left], items[smallest])) smallest = left;
      if (right < n && IndexedHeap.#lessThan(items[right], items[smallest])) smallest = right;
      if (smallest === index) break;
      this.#swap(index, smallest);
      index = smallest;
    }
  }

  /** @returns {number} Number of entries currently held. */
  get size() {
    return this.#items.length;
  }

  /**
   * Adds an entry.
   * @param {string} key Unique key.
   * @param {number} priority Ordering priority; smaller leaves first.
   * @returns {void}
   */
  push(key, priority) {
    IndexedHeap.#checkKey(key);
    IndexedHeap.#checkPriority(priority);
    if (this.#positions.has(key)) throw new Error(`duplicate key: "${key}"`);
    const entry = { key, priority, seq: this.#nextSeq };
    this.#nextSeq += 1;
    const index = this.#items.length;
    this.#items.push(entry);
    this.#positions.set(key, index);
    this.#siftUp(index);
  }

  /**
   * Reads the next entry without removing it.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  peek() {
    if (this.#items.length === 0) return undefined;
    const { key, priority } = this.#items[0];
    return { key, priority };
  }

  /**
   * Removes and returns the next entry.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  pop() {
    if (this.#items.length === 0) return undefined;
    const items = this.#items;
    const top = items[0];
    const last = items.pop();
    this.#positions.delete(top.key);
    if (items.length > 0) {
      items[0] = last;
      this.#positions.set(last.key, 0);
      this.#siftDown(0);
    }
    return { key: top.key, priority: top.priority };
  }

  /**
   * Reports whether a key is held.
   * @param {string} key Key to look up.
   * @returns {boolean} True when the key is held.
   */
  has(key) {
    IndexedHeap.#checkKey(key);
    return this.#positions.has(key);
  }

  /**
   * Reads the priority stored for a key.
   * @param {string} key Key to look up.
   * @returns {number | undefined} Stored priority, or undefined when absent.
   */
  priorityOf(key) {
    IndexedHeap.#checkKey(key);
    const index = this.#positions.get(key);
    return index === undefined ? undefined : this.#items[index].priority;
  }

  /**
   * Lowers the priority of a held key.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority; must not exceed the current one.
   * @returns {void}
   */
  decreaseKey(key, priority) {
    IndexedHeap.#checkKey(key);
    IndexedHeap.#checkPriority(priority);
    const index = this.#positions.get(key);
    if (index === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    const entry = this.#items[index];
    if (priority > entry.priority) throw new RangeError(`priority must not increase for "${key}"`);
    entry.priority = priority;
    this.#siftUp(index);
  }

  /**
   * Sets the priority of a held key in either direction.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority.
   * @returns {void}
   */
  setPriority(key, priority) {
    IndexedHeap.#checkKey(key);
    IndexedHeap.#checkPriority(priority);
    const index = this.#positions.get(key);
    if (index === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    const entry = this.#items[index];
    const oldPriority = entry.priority;
    entry.priority = priority;
    if (priority < oldPriority) this.#siftUp(index);
    else this.#siftDown(index);
  }

  /**
   * Removes a held key.
   * @param {string} key Key to remove.
   * @returns {boolean} True when an entry was removed.
   */
  remove(key) {
    IndexedHeap.#checkKey(key);
    const index = this.#positions.get(key);
    if (index === undefined) return false;
    const items = this.#items;
    const last = items.pop();
    this.#positions.delete(key);
    if (index < items.length) {
      items[index] = last;
      this.#positions.set(last.key, index);
      this.#siftDown(index);
      this.#siftUp(index);
    }
    return true;
  }

  /**
   * Empties the heap.
   * @returns {Array<{key: string, priority: number}>} Every entry in pop order.
   */
  drain() {
    const result = [];
    let next;
    while ((next = this.pop()) !== undefined) result.push(next);
    return result;
  }
}
